export function getValidatedHost(
	request: Request,
	baseUrl: string,
): string | null {
	const forwardedHost = request.headers.get('X-Forwarded-Host')
	const host = request.headers.get('host')
	const candidateHost = forwardedHost ?? host

	if (!candidateHost) {
		return null
	}

	const hostWithoutPort = candidateHost.split(':')[0]?.toLowerCase()

	if (!hostWithoutPort) {
		return null
	}

	if (
		hostWithoutPort === 'localhost' ||
		hostWithoutPort === '127.0.0.1' ||
		hostWithoutPort === '::1'
	) {
		return candidateHost
	}

	const baseUrlHost = new URL(baseUrl).hostname.toLowerCase()
	if (
		hostWithoutPort === baseUrlHost ||
		hostWithoutPort.endsWith(`.${baseUrlHost}`)
	) {
		return candidateHost
	}

	return null
}

import { promises as fs, constants } from 'node:fs'
import path from 'node:path'
import { invariantResponse } from '@epic-web/invariant'
import { getDomainUrl } from '@repo/common'
import { validateInstanceUrl } from '@repo/security'
import { getImgResponse } from 'openimg/node'
import { ENV } from 'varlock/env'
import { getSignedGetRequestInfoAsync } from '#app/utils/storage.server.ts'
import { type Route } from './+types/images'

let cacheDir: string | 'no_cache' | null = null

async function getCacheDir() {
	if (cacheDir) return cacheDir

	let dir: string | 'no_cache' = './tests/fixtures/openimg'
	if (ENV.NODE_ENV === 'production') {
		const isAccessible = await fs
			.access('/data', constants.W_OK)
			.then(() => true)
			.catch(() => false)

		if (isAccessible) {
			dir = '/data/images'
		} else {
			console.warn(
				'Production cache directory /data is not writable, disabling image cache',
			)
			dir = 'no_cache'
		}
	}

	return (cacheDir = dir)
}

export async function loader({ request }: Route.LoaderArgs) {
	const url = new URL(request.url)
	const searchParams = url.searchParams

	const headers = new Headers()
	headers.set('Cache-Control', 'public, max-age=31536000, immutable')

	const objectKey = searchParams.get('objectKey')
	const organizationId = searchParams.get('organizationId')

	return getImgResponse(request, {
		headers,
		allowlistedOrigins: [getDomainUrl(request), ENV.AWS_ENDPOINT_URL_S3].filter(
			Boolean,
		),
		cacheFolder: await getCacheDir(),
		getImgSource: async () => {
			if (objectKey) {
				const { url: signedUrl, headers: signedHeaders } =
					await getSignedGetRequestInfoAsync(objectKey, organizationId!)
				return {
					type: 'fetch',
					url: signedUrl,
					headers: signedHeaders,
				}
			}

			const src = searchParams.get('src')
			invariantResponse(src, 'src query parameter is required', { status: 400 })

			if (URL.canParse(src)) {
				const validation = validateInstanceUrl(src)
				if (!validation.valid) {
					throw new Error(`Invalid image URL: ${validation.reason}`)
				}
				// Fetch image from external URL; will be matched against allowlist
				return {
					type: 'fetch',
					url: src,
				}
			}

            // Prevent path traversal
            if (src.includes('..')) {
                throw new Error('Invalid image path')
            }

			// Retrieve image from filesystem (public folder)
			if (src.startsWith('/assets')) {
				// Files managed by Vite
				return {
					type: 'fs',
					path: '.' + src,
				}
			}
			// Fallback to files in public folder
			return {
				type: 'fs',
				path: './public' + src,
			}
		},
	})
}
